/**
 * A simple class to manage a counter.
 */
class Counter {
    /**
     * Initializes a new Counter instance with a starting value of 0.
     */
    constructor(initialValue = 0) {
        /**
         * The current value of the counter.
         * @type {number}
         */
        this.count = initialValue;
    }

    /**
     * Increments the counter by 1.
     * Increases the current count by one.
     * @returns {number} The new value of the counter after incrementing.
     */
    increment() {
        this.count += 1;
        return this.count;
    }

    /**
     * Resets the counter back to its initial value (0, or the value set in the constructor).
     * @returns {number} The value of the counter after resetting.
     */
    reset() {
        this.count = 0;
        return this.count;
    }

    /**
     * Gets the current value of the counter.
     * @returns {number} The current count.
     */
    getCount() {
        return this.count;
    }
}

