/**
 * Reads a text file and returns the total number of lines in it.
 *
 * @param {string} filePath The absolute or relative path to the text file.
 * @returns {Promise<number>} A promise that resolves with the number of lines.
 * @throws {Error} Throws an error if the file cannot be read (e.g., file not found, permissions issue).
 */
async function countLinesInFile(filePath: string): Promise<number> {
  try {
    // 1. Read the file content as a string
    const content = await fs.readFile(filePath, { encoding: 'utf8' });

    // 2. Split the content by newline characters.
    // The split method on a string by '\n' will produce an array where the
    // number of elements is one more than the number of lines (if the file
    // doesn't end with a newline) or exactly the number of lines (if it does).
    // A more robust way is to split by '\n' and filter out empty strings,
    // or simply count the occurrences of '\n'.

    // A simple and effective way is to split by '\n' and count the resulting array length.
    // We use .split(/\r?\n/) to handle both Windows (\r\n) and Unix (\n) line endings.
    const lines = content.split(/\r?\n/);

    // 3. Return the count of the lines
    return lines.length;

  } catch (error) {
    console.error(`Error reading file at ${filePath}:`, error instanceof Error ? error.message : error);
    // Re-throw the error so the caller knows the operation failed
    throw new Error(`Failed to count lines in file: ${filePath}`);
  }
}

