Throttling ensures that a function is executed at most once every specified time interval. This is very useful for handling events like scrolling, resizing, or rapid button clicks.

```javascript
/**
 * Creates a throttled version of a function that only invokes it at most once
 * per every wait milliseconds.
 *
 * @param {Function} func The function to throttle.
 * @param {number} wait The number of milliseconds to wait between invocations.
 * @returns {Function} A new function that throttles the original function.
 */
function throttle(func, wait) {
    let timeout = null;
    let lastArgs = null;
    let lastThis = null;
    let lastExecTime = 0;

    /**
     * The throttled function wrapper.
     * @param {...any} args Arguments passed to the throttled function.
     */
    return function(...args) {
        const context = this;
        const now = Date.now();

        // Check if enough time has passed since the last execution
        if (now - lastExecTime >= wait) {
            // Execute immediately
            lastExecTime = now;
            func.apply(context, args);
        } else {
            // If called too soon, store the latest arguments and schedule a call
            // for when the wait period is over.
            if (!timeout) {
                timeout = setTimeout(() => {
                    lastExecTime = Date.now();
