```typescript
/**
 * Fetches JSON data from a specified URL and returns the parsed JSON object.
 *
 * @param url The URL from which to fetch the JSON data.
 * @returns A Promise that resolves with the parsed JSON data, or rejects with an Error if the fetch fails or JSON parsing fails.
 */
function fetchJson<T>(url: string): Promise<T> {
  return fetch(url)
    .then(response => {
      // Check if the response status is OK (status code 200-299)
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status} for URL: ${url}`);
      }
      // Parse the response body as JSON
      return response.json() as Promise<T>;
    })
    .catch(error => {
      // Re-throw the error to be handled by the caller
      console.error(`Failed to fetch JSON from ${url}:`, error);
      // We cast the error to a more general Error type for consistency if needed,
      // but re-throwing the original error is often best practice.
      throw new Error(`Error fetching or parsing JSON: ${error instanceof Error ? error.message : String(error)}`);
    });
}

