  if (!snakeCaseString) {
    return "";
  }

  // 1. Split the string by the underscore character.
  const parts: string[] = snakeCaseString.split('_');

  // 2. The first part remains in lowercase.
  let camelCaseString: string = parts[0];

  // 3. Iterate over the rest of the parts and capitalize the first letter of each.
  for (let i = 1; i < parts.length; i++) {
    const part = parts[i];
    if (part.length > 0) {
      const capitalizedPart = part.charAt(0).toUpperCase() + part.slice(1);
      camelCaseString += capitalizedPart;
    }
  }

  return camelCaseString;
}

