const camel2 = snakeToCamelCase(example2);
console.log(`Original: ${example2} -> CamelCase: ${camel2}`); // Output: userFirstNameId

const example3 = "singleword";
const camel3 = snakeToCamelCase(example3);
console.log(`Original: ${example3} -> CamelCase: ${camel3}`); // Output: singleword

const example4 = "";
const camel4 = snakeToCamelCase(example4);
console.log(`Original: "${example4}" -> CamelCase: "${camel4}"`); // Output: ""
```

