```c
#include <stdio.h>

/**
 * @brief Computes the factorial of a non-negative integer n.
 * 
 * The factorial of a non-negative integer n, denoted by n!, is the product 
 * of all positive integers less than or equal to n.
 * By definition, 0! is 1.
 * 
 * @param n The non-negative integer for which to compute the factorial.
 * @return long long The factorial of n. Returns 1 for n=0.
 *         Returns -1 if n is negative (indicating an error, though 
 *         for this implementation, we handle it by returning 1 or 0 based on context).
 */
long long factorial(int n) {
    // Handle the case for negative input
    if (n < 0) {
        fprintf(stderr, "Error: Factorial is not defined for negative numbers.\n");
        return -1; // Return a sentinel value to indicate an error
    }

    // Base case: 0! = 1
    if (n == 0) {
        return 1;
    }

    // Iterative calculation
    long long result = 1;
    for (int i = 1; i <= n; i++) {
        result *= i;
    }

    return result;
}

int main() {
    int num1 = 5;
    long long fact1 = factorial(num1);
    if (fact1 != -1) {
        printf("Factorial of %d is: %lld\n", num1, fact1); // Output: 120
    }

    int num2 = 0;
    long long fact2 = factorial(num2);
    if (fact2 != -1) {
        printf("Factorial of %d is: %lld\n", num2, fact2); // Output: 1
    }

    int num3 = 10;
    long long fact3 = factorial(num3);
    if (fact3 != -1) {
        printf("Factorial of %d is: %lld\n", num3, fact3); // Output: 3628800
    }

    int num4 = -3;
    long long fact4 = factorial(num4);
    if (fact4 == -1) {
        printf("Factorial of %d failed (as expected).\n", num4);
    }

    return 0;
}
```

