/// Finds the largest element in a slice of i32.
///
/// # Arguments
///
/// * `slice` - A slice of i32 integers to search through.
///
/// # Returns
///
/// An `Option<i32>` containing the largest element if the slice is not empty,
/// or `None` if the slice is empty.
fn find_largest(slice: &[i32]) -> Option<i32> {
    // Check if the slice is empty. If it is, there is no largest element.
    if slice.is_empty() {
        return None;
    }

    // Initialize the maximum value with the first element of the slice.
    let mut max_val = slice[0];

    // Iterate over the rest of the elements (starting from the second element).
    for &element in slice.iter().skip(1) {
        // If the current element is greater than the current maximum, update max_val.
        if element > max_val {
            max_val = element;
        }
    }

    // Return the found maximum value wrapped in Some.
    Some(max_val)
}

