    println!("Finding largest in {:?}: {:?}", data2, find_largest(&data2));
    println!("Finding largest in {:?}: {:?}", data3, find_largest(&data3));
    println!("Finding largest in {:?}: {:?}", data4, find_largest(&data4));
}
